      's10.applications': { label: 'التطبيقات العلمية ذات الصلة', hint: 'دراسات في السينما والتلفزيون استخدمت المنظور، مع الاستشهادات.', ph: '' },
      's10.debates': { label: 'النقاشات النظرية والحدود', hint: 'الانتقادات والحدود مع الاستشهادات.', ph: '' },
